		get
			if (_bundlePath == null)
				_bundlePath = Application.streamingAssetsPath + "/";
			return _bundlePath;
	public static void LoadBundle()
		if (bundleLoaded)
			return;
		bundleDict[BundleType.Core] = AssetBundle.LoadFromFile(BundlePath + "core");
		coreBundle = bundleDict[BundleType.Core];
		bundleDict[BundleType.Sfx] = AssetBundle.LoadFromFile(BundlePath + "sfx");
		bundleDict[BundleType.Bgm] = null;
		foreach (AssetBundle value in bundleDict.Values)
			if (value != null)
				value.LoadAllAssets<Object>();
		bundleLoaded = true;
	public static IEnumerator LoadBGMAsync(string givenName)
		while (bgmLoadInProgress)
			yield return null;
		bgmLoadInProgress = true;
		AssetBundleCreateRequest abcr = AssetBundle.LoadFromFileAsync(BundlePath + givenName);
		abcr.allowSceneActivation = true;
		yield return abcr;
		while (!abcr.isDone)
			yield return null;
		bundleDict[BundleType.Bgm] = abcr.assetBundle;
		yield return null;
		bgmLoadInProgress = false;
	public static T GetWithComponent<T>(string assetPath) where T : Component
		return Get(assetPath).GetComponent<T>();
	public static T Get<T>(string assetPath) where T : Object
		return coreBundle.LoadAsset<T>(assetPath);
	public static T[] GetWithSubAssets<T>(string assetPath) where T : Object
		return coreBundle.LoadAssetWithSubAssets<T>(assetPath);
		return Get<GameObject>(assetPath);
	public static void LoadBGM(string givenName)
		if (!(lastBGM == givenName) && !(givenName == string.Empty))
			lastBGM = givenName;
			if (bundleDict[BundleType.Bgm] != null)
				bundleDict[BundleType.Bgm].Unload(unloadAllLoadedObjects: false);
			if (GameController.Instance != null)
				GameController.Instance.StartCoroutine(LoadBGMAsync(lastBGM));
	public static AudioClip GetBGM(string assetPath)
		return (!(bundleDict[BundleType.Bgm] == null)) ? bundleDict[BundleType.Bgm].LoadAsset<AudioClip>(assetPath) : null;
	public static AudioClip GetSFX(string assetPath)
		return bundleDict[BundleType.Sfx].LoadAsset<AudioClip>(assetPath);
